'use strict';
function providerName(){return aiProvider==='chatgpt'?'ChatGPT · ваш план':aiProvider==='ollama'?'Локальная модель Ollama':aiConfigured?'Модель через API':'Модель не подключена'}
async function connectionSettings(){if(!online){modal('Подключить AI-помощника',`<p>ChatGPT, локальная модель и API доступны в полной версии с Go-сервером. Веб-версия разбирает данные по правилам.</p><button class="btn primary full" data-action="close">Понятно</button>`);return}let s={};try{s=await api('/api/chatgpt/status')}catch{}modal('Как будет работать помощник',`<p>Выберите источник ответов. Платный API остаётся дополнительным вариантом.</p><div class="connect-option"><span class="ai-badge">${icon('spark')}</span><div><strong>Ваш план ChatGPT</strong><p>${s.sharing?'Аккаунт подключён. Выберите модель.':'Для подходящей подписки · расходуются её лимиты'}</p></div><button class="btn dark" data-connection="${s.sharing?'chatgpt-model':'chatgpt-start'}">${s.sharing?'Модель':'Continue with ChatGPT'}</button></div>${s.connected?`<div class="connection-account"><span>${esc(s.email||'ChatGPT подключён')}</span><a href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">Управлять использованием ↗</a><button class="text-btn" data-connection="chatgpt-logout">Отключить</button></div>`:''}<div class="connect-option"><span class="ai-badge">${icon('coffee')}</span><div><strong>Ollama на компьютере</strong><p>Без платы за API · нужна установленная локальная модель</p></div><button class="btn soft" data-connection="ollama">Выбрать</button></div><div class="connect-option"><span class="ai-badge">${icon('link')}</span><div><strong>OpenAI-совместимый API</strong><p>Ключ вашего провайдера · отдельная оплата</p></div><button class="btn soft" data-connection="api">Настроить</button></div><p class="inline-note">ChatGPT подключается через официальный вход OpenAI. История ваших разговоров не передаётся Ритму. Возможность использовать план зависит от аккаунта и выданных разрешений.</p>`)}
function apiSettingsModal(){modal('Подключить модель через API',`<p>Проверка отправит один короткий запрос. После перезапуска потребуется подключиться заново. Запросы оплачиваются по тарифу провайдера.</p><form id="ai-config-form" autocomplete="off"><div class="field"><label for="ai-base">Адрес API</label><input id="ai-base" name="baseURL" type="url" value="https://api.openai.com/v1" required></div><div class="field"><label for="ai-model">Доступная модель</label><input id="ai-model" name="model" placeholder="Идентификатор модели провайдера" maxlength="200" required></div><div class="field"><label for="ai-key">API-ключ</label><input id="ai-key" name="key" type="password" autocomplete="new-password" minlength="8" maxlength="1000" required></div><p class="inline-note">Для ответов выбранная модель получает финансовую сводку.</p><div class="field-error" id="ai-error" role="alert"></div><button class="btn primary full" type="submit">Подключить и проверить</button></form>`)}
function ollamaSettings(){modal('Локальная модель без платы за API',`<p>Ollama выполняет модель на вашем компьютере. Данные не отправляются внешнему AI-провайдеру. Нужны установленная Ollama и загруженная модель.</p><pre class="code-snippet">ollama pull qwen2.5:3b</pre><form id="ollama-form"><div class="field"><label for="ollama-model">Имя установленной модели</label><input id="ollama-model" name="model" value="qwen2.5:3b" maxlength="200" required></div><p class="inline-note">Сервер подключится к 127.0.0.1:11434. Скорость и качество зависят от модели и компьютера. Если Ollama не запущена, появится ошибка подключения.</p><div class="field-error" id="ollama-error" role="alert"></div><button class="btn primary full" type="submit">Проверить локальную модель</button></form>`)}
async function chatGPTModels(){modal('Использовать ваш план ChatGPT',`<p>Загружаем модели, доступные подключённому аккаунту…</p>`);try{const r=await api('/api/chatgpt/models');if(!r.models.length)throw Error('Каталог моделей пуст. Проверьте разрешение на использование плана.');$('#modal-body').innerHTML=`<p>Ответы будут использовать ваш план ChatGPT или доступные кредиты в пределах его настроек. Отдельный API-ключ не требуется.</p><form id="chatgpt-model-form"><div class="field"><label for="chatgpt-model">Модель вашего аккаунта</label><select id="chatgpt-model" name="model">${r.models.map(m=>`<option value="${esc(m.slug)}">${esc(m.display_name||m.slug)}</option>`).join('')}</select></div><p class="inline-note">Доступ к модели подтверждается успешно завершённым ответом. <a class="text-btn" href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">Управлять использованием ↗</a></p><div class="field-error" id="chatgpt-error" role="alert"></div><button class="btn primary full" type="submit">Выбрать модель</button></form>`}catch(e){$('#modal-body').innerHTML=`<p>${esc(e.message)}</p><button class="btn primary full" data-action="close">Понятно</button>`}}
async function initConnection(){if(!online)return;try{const s=await api('/api/chatgpt/status');if(s.error)notify(s.error);if(s.sharing&&aiProvider!=='chatgpt')await chatGPTModels()}catch{}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-connection]');if(!b)return;const action=b.dataset.connection;if(action==='api'){apiSettingsModal();return}if(action==='ollama'){ollamaSettings();return}if(action==='chatgpt-model'){chatGPTModels();return}if(action==='chatgpt-start'){b.disabled=true;b.textContent='Открываем вход…';try{const r=await post('/api/chatgpt/start',{});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='auth.openai.com')throw Error('Неожиданный адрес авторизации');window.location.assign(u.href)}catch(err){notify(err.message);b.disabled=false;b.textContent='Continue with ChatGPT'}}if(action==='chatgpt-logout'){b.disabled=true;try{const r=await post('/api/chatgpt/logout',{});aiConfigured=false;aiProvider='';closeModal();render();notify(r.revoked?'Подключение ChatGPT отключено':'Отключено локально. Отзыв сессии подтвердите в настройках ChatGPT.')}catch(err){notify(err.message);b.disabled=false}}});
document.addEventListener('submit',async e=>{if(e.target.id==='ollama-form'){e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;b.textContent='Проверяем модель…';try{await post('/api/ai/config',{provider:'ollama',baseURL:'http://127.0.0.1:11434/v1',model:$('#ollama-model').value,key:'local-ollama'});aiConfigured=true;aiProvider='ollama';closeModal();render();notify('Локальная модель ответила. Помощник подключён.')}catch(err){$('#ollama-error').textContent=err.message;b.disabled=false;b.textContent='Проверить локальную модель'}}if(e.target.id==='chatgpt-model-form'){e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await post('/api/chatgpt/select',{model:$('#chatgpt-model').value});aiConfigured=true;aiProvider='chatgpt';closeModal();render();notify('Ритм использует ваш план ChatGPT. Можно отправить вопрос.')}catch(err){$('#chatgpt-error').textContent=err.message;b.disabled=false}}});
